using Cortex.Video.Editing;
namespace Cortex.Video.Composition;
/// <summary>Validates authored data against exact installed capabilities before accepting a plan or human patch.</summary>
public static class EditorialCompositionCatalogValidation {
    public static void Validate(EditorialDecisionPlanDocument plan,HelengineCapabilities catalog,IReadOnlySet<string>? mediaIds=null) {
        var effective=EditorialDecisionMerge.Effective(plan);EditorialDecisionValidation.ThrowIfInvalid(effective);foreach(var scene in effective.Scenes) {var edit=scene.Proposal.Editing;if(edit is null)continue;if(edit.Transform is{} transform) {foreach(var pair in new Dictionary<string,double>{{"position_x",transform.PositionX},{"position_y",transform.PositionY},{"scale_x",transform.ScaleX},{"scale_y",transform.ScaleY},{"rotation_deg",transform.RotationDeg},{"opacity",transform.Opacity}})catalog.ValidateProperty(pair.Key,pair.Value);}
            if(edit.Animations.Select(animation=>animation.Property).Distinct().Count()!=edit.Animations.Count)throw new InvalidDataException("Use one animation track per property.");foreach(var animation in edit.Animations)foreach(var frame in animation.Keyframes) {catalog.ValidateProperty(animation.Property,frame.Value);if(!catalog.Curves.Contains(frame.Curve))throw new InvalidDataException("Unknown animation curve version.");}
            foreach(var effect in edit.Effects) {catalog.ValidateEffect(effect.Id,effect.Version,effect.Parameters);var descriptor=catalog.Effect(effect.Id,effect.Version);if(descriptor.GetProperty("category").GetString()!="layer")throw new InvalidDataException("Unknown layer effect.");var roles=descriptor.GetProperty("input_roles").EnumerateArray().Select(role=>role.GetString()!).Where(role=>role!=descriptor.GetProperty("main_input_role").GetString()).ToHashSet();if(roles.Any(role=>!effect.Inputs.ContainsKey(role)) || effect.Inputs.Keys.Any(role=>!roles.Contains(role)))throw new InvalidDataException("Effect input roles are incomplete or unknown.");if(mediaIds!=null && effect.Inputs.Values.Any(id=>!mediaIds.Contains(id)))throw new InvalidDataException("Effect source does not belong to this project.");}
            if(edit.Mask is{} mask && (mask.Channel is not("alpha" or "luma") || mediaIds!=null && !mediaIds.Contains(mask.MediaId)))throw new InvalidDataException("Mask requires a current owned material.");if(edit.Transition is{} transition) {catalog.ValidateEffect(transition.EffectId,transition.EffectVersion,transition.Parameters);if(catalog.Effect(transition.EffectId,transition.EffectVersion).GetProperty("category").GetString()!="transition")throw new InvalidDataException("Unknown visual transition.");}if(mediaIds!=null && edit.Audio.Any(audio=>!mediaIds.Contains(audio.MediaId)))throw new InvalidDataException("Audio source does not belong to this project.");
        }
    }
}
